sys_script_include.script:
var TradingCompanionEngine = Class.create();
TradingCompanionEngine.prototype = {

    initialize: function() {},

    run: function() {
        gs.info("Trading Companion: engine started");

        var gr = new GlideRecord('x_461782_trading_0_trading_watchlist_item');
        gr.addQuery('active', true);
        gr.query();

        while (gr.next()) {
            gs.info("Checking: " + gr.symbol);
            this.checkRules(gr);
        }

        gs.info("Trading Companion: engine finished");
    },

    checkRules: function(watchItem) {

        var rules = new GlideRecord('x_461782_trading_0_trading_alert_rule');
        rules.addQuery('watchlist_item', watchItem.sys_id);
        rules.addQuery('active', true);
        rules.query();

        while (rules.next()) {
            gs.info("Evaluating rule: " + rules.rule_name);
        }

    },

    type: 'TradingCompanionEngine'
};
